package dev.gbppimentel.snapcompanion.next;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.json.*;import java.io.*;import static org.junit.Assert.*;
/** Standard local dump boundary; does not start game/capture services or access a device. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class ServiceMetricsTest {
 @Test public void captureDumpReportsMeasurementMeaningsWithoutGameplayOrIdentityData()throws Exception{CaptureService s=Robolectric.buildService(CaptureService.class).get();StringWriter text=new StringWriter();s.dump(null,new PrintWriter(text),new String[]{"ignored"});String raw=text.toString().trim();assertTrue(raw.startsWith("snap-metrics|"));JSONObject r=new JSONObject(raw.substring(raw.indexOf('|')+1));assertEquals(2,r.getInt("schema"));assertFalse(r.getString("session").isEmpty());assertTrue(r.has("sourceEpoch"));assertTrue(r.has("failedInferenceMillis"));assertEquals("capture",r.getString("kind"));assertTrue(r.has("successfulInferenceMillis"));assertTrue(r.has("targetHz"));assertFalse(r.has("rawText"));assertFalse(r.has("profile"));assertFalse(r.has("photos"));assertFalse(r.has("user"));}
 @Test public void linkDumpRemainsNeutralWithoutAnActiveProof()throws Exception{boolean active=EdenLinkService.active;GameConnection old=EdenLinkService.connection;try{EdenLinkService.active=false;EdenLinkService.connection=GameConnection.empty();EdenLinkService s=Robolectric.buildService(EdenLinkService.class).get();StringWriter text=new StringWriter();s.dump(null,new PrintWriter(text),new String[0]);JSONObject r=new JSONObject(text.toString().trim().split("\\|",2)[1]);assertFalse(r.getBoolean("gameVerified"));assertFalse(r.getBoolean("gameVisible"));assertFalse(r.has("user"));assertFalse(r.has("requests"));}finally{EdenLinkService.active=active;EdenLinkService.connection=old;}}
}
